-- CONNECT SYSTEM
ALTER SESSION SET EVENTS '10150 TRACE NAME CONTEXT FOREVER, LEVEL 1';
-- new object type path: SCHEMA_EXPORT/USER
 CREATE USER "SCOTT" IDENTIFIED BY VALUES 'S:ABC;T:DEF'
      DEFAULT TABLESPACE "APP_DATA"
      TEMPORARY TABLESPACE "TEMP2";
-- new object type path: SCHEMA_EXPORT/SYSTEM_GRANT
GRANT CREATE SESSION TO "SCOTT";
-- new object type path: SCHEMA_EXPORT/ROLE_GRANT
 GRANT "CONNECT" TO "SCOTT";
 GRANT "APP_READER" TO "SCOTT";
-- new object type path: SCHEMA_EXPORT/TABLESPACE_QUOTA
DECLARE
  TEMP_COUNT NUMBER;
BEGIN
  SQLSTR := 'ALTER USER "SCOTT" QUOTA UNLIMITED ON "APP_DATA"';
END;
/
-- new object type path: SCHEMA_EXPORT/SEQUENCE/SEQUENCE
-- CONNECT SCOTT
 CREATE SEQUENCE  "SCOTT"."EMP_SEQ"  MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  GLOBAL ;
-- new object type path: SCHEMA_EXPORT/TABLE/TABLE
CREATE TABLE "SCOTT"."DEPT" 
   (	"DEPTNO" NUMBER(2,0), 
	"DNAME" VARCHAR2(14 BYTE), 
	"LOC" VARCHAR2(13 CHAR)
   ) SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  TABLESPACE "APP_DATA" ;
CREATE TABLE "SCOTT"."EMP" 
   (	"EMPNO" NUMBER(4,0), 
	"ENAME" VARCHAR2(10 BYTE), 
	"NOTE" CLOB,
	"DEPTNO" NUMBER(2,0)
   ) TABLESPACE "APP_DATA" 
 LOB ("NOTE") STORE AS SECUREFILE (
  TABLESPACE "APP_LOB" ENABLE STORAGE IN ROW) ;
-- new object type path: SCHEMA_EXPORT/TABLE/GRANT/OWNER_GRANT/OBJECT_GRANT
GRANT SELECT ON "SCOTT"."EMP" TO "REPORTS";
GRANT SELECT ON "HR"."JOBS" TO "SCOTT";
-- new object type path: SCHEMA_EXPORT/TABLE/INDEX/INDEX
CREATE UNIQUE INDEX "SCOTT"."PK_EMP" ON "SCOTT"."EMP" ("EMPNO") 
  TABLESPACE "APP_IDX" ;
-- new object type path: SCHEMA_EXPORT/TABLE/CONSTRAINT/REF_CONSTRAINT
ALTER TABLE "SCOTT"."EMP" ADD CONSTRAINT "FK_DEPTNO" FOREIGN KEY ("DEPTNO")
	  REFERENCES "SCOTT"."DEPT" ("DEPTNO") ENABLE;
-- new object type path: SCHEMA_EXPORT/PACKAGE/PACKAGE_SPEC
CREATE EDITIONABLE PACKAGE "SCOTT"."PKG" AS
  PROCEDURE p;
END;
/
-- new object type path: SCHEMA_EXPORT/PACKAGE/PACKAGE_BODY
CREATE EDITIONABLE PACKAGE BODY "SCOTT"."PKG" AS
  PROCEDURE p IS BEGIN INSERT INTO t VALUES (1); END;
END;
/
-- new object type path: SCHEMA_EXPORT/SYNONYM/SYNONYM
CREATE SYNONYM "SCOTT"."JOBS" FOR "HR"."JOBS";
CREATE SYNONYM "SCOTT"."REM" FOR "X"."Y"@"OTHERDB";
-- new object type path: SCHEMA_EXPORT/DB_LINK
CREATE DATABASE LINK "OTHERDB.WORLD" CONNECT TO "U" IDENTIFIED BY VALUES ':1' USING 'prod';
-- new object type path: SCHEMA_EXPORT/VIEW/VIEW
CREATE FORCE EDITIONABLE VIEW "SCOTT"."V_EMP" ("EMPNO") AS 
  SELECT empno FROM emp;
